import{z as s,x as o,o as e,c as D,q as n,j as t,D as A,d as B,s as l,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"实验跟踪","description":"","frontmatter":{"title":"实验跟踪","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-experiment-tracking.md","filePath":"llm/ti-experiment-tracking.md","lastUpdated":1791413859000}'),d={name:"llm/ti-experiment-tracking.md"};function p(m,E,u,C,h,g){const r=o("Mermaid");return e(),D("div",null,[E[2]||(E[2]=n('<h1 id="实验跟踪" tabindex="-1">实验跟踪 <a class="header-anchor" href="#实验跟踪" aria-label="Permalink to &quot;实验跟踪&quot;">​</a></h1><div class="epigraph"><p>实验跟踪系统是研究组的记忆：没有它，三个月后无人能答「这个模型是哪次 run、用什么数据、改了哪行配置训出来的」。</p><footer>—— 据 MLflow、Weights &amp; Biases 等跟踪系统与大规模训练团队实践整理</footer></div><p><a href="/llm/ti-hparam-search-eng">上一课</a>把搜索产出收成「响应面入档」，入档默认了一个系统的存在。本课把这个系统补全：实验跟踪。前几课埋的纪律在此汇合——step 钩子产出的标量、<a href="/llm/ti-loss-curve-reading">判读设施</a>要求的配置哈希、<a href="/llm/ti-checkpoint-engineering">检查点元数据</a>里的数据指纹，都需要一个统一的家。本课写 run 的身份、要记什么、怎么查，以及为什么自建不如采用现成系统。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有跟踪系统的团队靠三种脆弱载体记实验：目录名（<code>run_v3_final_real</code>）、个人笔记、口头记忆。三者共同的失败是<strong>链条断裂</strong>：评测表上有一条好成绩，反向找训练 run 时，目录已被清理或从未关联；正向复现时，配置文件改过三轮，当时那份只在某个人的未提交改动里。链条断裂的代价随团队规模复利：重复已失败的实验、把别人的模型当自己的基线、审计时拿不出「数据从哪来」的证据。</p><p><span class="marginnote">术语翻译：配置哈希就是把整套训练配置（学习率、批大小、层数……）序列化成文本后算出的指纹——内容变一个字符，哈希就变。数据指纹同理，钉住「喂了哪些数据」。四元组合起来相当于 run 的身份证：指纹相同才谈得上复现，不同则能精确指出差在哪一项。</span></p><h3 id="run-的身份与最低记录" tabindex="-1">run 的身份与最低记录 <a class="header-anchor" href="#run-的身份与最低记录" aria-label="Permalink to &quot;run 的身份与最低记录&quot;">​</a></h3><p>一次 run 的身份由四元组钉死：配置哈希（含配方版本）、代码版本、数据指纹、种子。最低记录三层：<strong>标量</strong>——逐步损失与吞吐，由第一课的钩子自动写入；<strong>工件</strong>——检查点指针、评测表、外部链接，工件只存指针不存副本，权威在检查点课的分线目录里；<strong>人话</strong>——动机一句话、结果判词一句（win/lose/inconclusive）、死因若被杀。判词字段最常被省略也最值钱：查询系统知道所有曲线，只有人知道「这次实验证明了什么」。</p><p><span class="marginnote">验收跟踪系统的硬标准：任取一个模型文件，能否在十分钟内走通「模型 → run → 配置哈希 + 数据指纹 + 检查点指针」的链条，并从链条任一端反向走回？走不通的环节就是要补的记录。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地三条。其一，<strong>采集自动化</strong>：身份四元组与标量由训练作业启动时自动上报，不依赖人工填写；人工只填动机与判词两个自由文本字段——凡是要求人工手抄哈希的系统，最终得到的是空字段。其二，<strong>对比守纪律</strong>：系统支持任意两条曲线叠加，但叠加是否有效由调用方按判读课的口径判断——配置哈希只在声明维度上不同才可比，跟踪系统记录事实，不担保可比性。其三，<strong>查询当接口</strong>：团队的高频问题是「某某方向试过没有、最好成绩多少、死在哪」，这些应当是查询而不是会议；搜索课的响应面、收束课的决策单，都以它为存储层。</p>',11)),(e(),t(i,null,{default:A(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22run%20%E5%90%AF%E5%8A%A8%3A%20%E4%B8%8A%E6%8A%A5%E8%BA%AB%E4%BB%BD%E5%9B%9B%E5%85%83%E7%BB%84%22%5D%20--%3E%20S%5B%22%E6%A0%87%E9%87%8F%E6%B5%81%3A%20%E6%8D%9F%E5%A4%B1%20%2F%20%E5%90%9E%E5%90%90%20%2F%20%E6%95%B0%E5%80%BC%E6%96%AD%E8%A8%80%22%5D%0A%20%20R%20--%3E%20A%5B%22%E5%B7%A5%E4%BB%B6%E6%8C%87%E9%92%88%3A%20%E6%A3%80%E6%9F%A5%E7%82%B9%20%2F%20%E8%AF%84%E6%B5%8B%E8%A1%A8%22%5D%0A%20%20R%20--%3E%20H%5B%22%E4%BA%BA%E5%B7%A5%E5%AD%97%E6%AE%B5%3A%20%E5%8A%A8%E6%9C%BA%20%2B%20%E5%88%A4%E8%AF%8D%22%5D%0A%20%20S%20--%3E%20DB%5B%22%E8%B7%9F%E8%B8%AA%E5%BA%93%22%5D%0A%20%20A%20--%3E%20DB%0A%20%20H%20--%3E%20DB%0A%20%20DB%20--%3E%20Q%5B%22%E6%9F%A5%E8%AF%A2%3A%20%E8%AF%95%E8%BF%87%E4%BB%80%E4%B9%88%20%2F%20%E6%9C%80%E5%A5%BD%E5%A4%9A%E5%B0%91%20%2F%20%E4%B8%BA%E4%BD%95%E6%AD%BB%22%5D%0A%20%20DB%20--%3E%20L%5B%22%E8%B0%B1%E7%B3%BB%3A%20%E6%A8%A1%E5%9E%8B%E5%88%B0%E6%95%B0%E6%8D%AE%E6%8C%87%E7%BA%B9%E5%8F%8C%E5%90%91%E8%B5%B0%E9%80%9A%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[B("跟踪有效的机理是"),a("strong",null,"把记忆外置成数据库"),B("：个人记忆的检索靠资历，数据库的检索靠字段；判词字段把「人才知道的部分」结构化，其余全部自动化。工件存指针不存副本的机理与发布分线一致：检查点目录是权威事实，跟踪库是索引，两处都存全量必然漂移。对比的机理照搬判读课：系统降低画错图的成本，不消除画错图的可能——所以口径检查留在人这边。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"常见误区：初学者容易以为把检查点、评测表也复制一份进跟踪库「更保险」，实际上两处存全量必然漂移——哪天原件被清理，副本和权威谁对谁错就说不清了。存指针、留权威，让事实只有一处说了算，索引跟着走。")],-1)),E[6]||(E[6]=a("p",null,"自建不如采用的机理更直接：跟踪系统的难点不在写入，在查询界面、多项目组织、长期迁移这些无聊工程；开源系统已把无聊部分做平，自建团队的收益只剩字段定制，而字段定制恰是配置化就能解决的。",-1)),(e(),t(i,null,{default:A(()=>[l(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%83%B3%E5%8F%A0%E5%8A%A0%E5%AF%B9%E6%AF%94%E4%B8%A4%E6%9D%A1%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20I%7B%22%E8%BA%AB%E4%BB%BD%E5%9B%9B%E5%85%83%E7%BB%84%E5%93%AA%E4%B8%80%E9%A1%B9%E4%B8%8D%E5%90%8C%3F%22%7D%0A%20%20I%20--%3E%7C%22%E4%BB%85%E9%85%8D%E7%BD%AE%E5%93%88%E5%B8%8C%2C%20%E4%B8%94%E5%B7%AE%E5%9C%A8%E5%A3%B0%E6%98%8E%E7%BB%B4%E5%BA%A6%22%7C%20OK%5B%22%E5%8F%AF%E6%AF%94%3A%20%E5%8F%A0%E5%8A%A0%E5%B9%B6%E6%A0%87%E6%B3%A8%E5%B7%AE%E5%BC%82%22%5D%0A%20%20I%20--%3E%7C%22%E4%BB%A3%E7%A0%81%E7%89%88%E6%9C%AC%E4%B8%8D%E5%90%8C%22%7C%20NG%5B%22%E5%85%88%E5%88%A4%E5%AE%9A%E6%98%AF%E5%90%A6%E5%BD%B1%E5%93%8D%E8%AF%AD%E4%B9%89%22%5D%0A%20%20I%20--%3E%7C%22%E6%95%B0%E6%8D%AE%E6%8C%87%E7%BA%B9%E4%B8%8D%E5%90%8C%22%7C%20ND%5B%22%E4%B8%8D%E5%90%8C%E6%95%B0%E6%8D%AE%3A%20%E5%8F%AA%E4%BD%9C%E8%B6%8B%E5%8A%BF%E5%8F%82%E8%80%83%22%5D%0A%20%20I%20--%3E%7C%22%E7%A7%8D%E5%AD%90%E4%B8%8D%E5%90%8C%22%7C%20SE%5B%22%E5%90%8C%E9%85%8D%E7%BD%AE%E5%A4%9A%E7%A7%8D%E5%AD%90%3A%20%E7%9C%8B%E6%96%B9%E5%B7%AE%E5%B8%A6%22%5D%0A%20%20NG%20--%3E%7C%22%E6%9C%89%E5%BD%B1%E5%93%8D%22%7C%20NO%5B%22%E4%B8%8D%E5%8F%AF%E6%AF%94%3A%20%E8%A1%A5%E5%AF%B9%E9%BD%90%E5%AE%9E%E9%AA%8C%22%5D%0A%20%20NG%20--%3E%7C%22%E6%97%A0%E5%BD%B1%E5%93%8D%22%7C%20OK%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=n('<p><span class="marginnote">为什么重要：「查询当接口」意味着「这个方向试过没有」从一次会议变成一条查询。按一场消融两万美元计，跟踪系统每月拦住一次重复失败实验，就够付它全部的部署与维护成本——这是少数投入产出比可以直接算出来的基础设施。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>跟踪系统不生产可比性：垃圾进垃圾出，配置哈希覆盖不到的改动（手改的脚本、未版本化的数据清洗）依然留下不可比曲线。它也不替代归档：判定死亡并写成死因归档是后一课的流程，跟踪库只保证「查得到」，不保证「读得懂」。指标口径本身（每 token CE 还是 PPL）由判读课统一，跟踪库照单全收，改口径等于换轴，旧曲线作废要标注。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>run 身份四元组：配置哈希、代码版本、数据指纹、种子；采集自动化，人工只填动机与判词。</li><li>工件存指针不存副本，权威在检查点分线目录。</li><li>跟踪库是团队记忆：试过什么、最好多少、为何死，应当查询可得而非开会口传。</li><li>验收标准是模型与配置之间的双向谱系十分钟走通。</li><li>出处：据 MLflow、Weights &amp; Biases 文档与大规模训练团队实践整理；对比纪律见<a href="/llm/ti-loss-curve-reading">loss 曲线的解读</a>。</li></ul>',5))])}const f=s(d,[["render",p]]);export{c as __pageData,f as default};
